import 'package:flutter/material.dart';import 'package:speech_to_text/speech_to_text.dart';import '../services/assistant_controller.dart';class ChatScreen extends StatefulWidget{const ChatScreen({super.key});@override State<ChatScreen> createState()=>_S();}class _S extends State<ChatScreen>{final c=TextEditingController();final sp=SpeechToText();bool listening=false,busy=false;final msgs=<Map<String,String>>[];Future<void>send(String s)async{if(s.trim().isEmpty||busy)return;setState((){msgs.add({'r':'u','t':s});busy=true;c.clear();});try{final r=await AssistantController.handle(s);setState(()=>msgs.add({'r':'a','t':r}));}catch(e){setState(()=>msgs.add({'r':'a','t':'❌ $e'}));}finally{setState(()=>busy=false);}}Future<void>listen()async{if(listening){await sp.stop();setState(()=>listening=false);return;}if(await sp.initialize()){setState(()=>listening=true);await sp.listen(localeId:'ar_EG',onResult:(r){if(r.finalResult){setState(()=>listening=false);send(r.recognizedWords);}});}}@override Widget build(BuildContext x)=>Scaffold(appBar:AppBar(title:const Text('مساعد الإدارة')),body:Column(children:[Expanded(child:msgs.isEmpty?const Center(child:Text('اتكلم طبيعي…\nمثال: أحمد عليه 3500 هيدفع الخميس ذكرني الأربعاء',textAlign:TextAlign.center)):ListView.builder(itemCount:msgs.length,itemBuilder:(c,i){final m=msgs[i];return Align(alignment:m['r']=='u'?Alignment.centerLeft:Alignment.centerRight,child:Card(child:Padding(padding:const EdgeInsets.all(12),child:Text(m['t']!))));})),if(busy)const LinearProgressIndicator(),Padding(padding:const EdgeInsets.all(8),child:Row(children:[IconButton(onPressed:listen,icon:Icon(listening?Icons.mic_off:Icons.mic)),Expanded(child:TextField(controller:c,onSubmitted:send,decoration:const InputDecoration(hintText:'اكتب ما تريد تسجيله…',border:OutlineInputBorder()))),IconButton(onPressed:()=>send(c.text),icon:const Icon(Icons.send))]))]));}}
